r"""
Scorecard Automation - local launcher (browser version, self-contained)
=========================================================================

Double-click this ONE file. Nothing else needed - your three scripts are
embedded inside it. It serves a small control panel on 127.0.0.1, opens your
browser at it, and runs the three scripts on request:

    1. PBQT Revoked & Closed tickets (Morningstar Jira Cloud)
    2. Combined Production Master Sheet
    3. Scorecard Automation

HOW "EMBEDDED" WORKS
--------------------
The three scripts' full source is stored below as base64 text. The first
time this launcher runs, it decodes each one and writes it out as a real
.py file into a "scripts" folder created next to this launcher - that is
what actually gets executed (each script still needs to run as its own
process; see below). On every later run, if that .py file already exists,
it is left completely alone - so if you open one in a text editor and tweak
it (say, to fix an email address or add a column code), your edit sticks.
To go back to the version shipped in this launcher, use the "Restore
original" link under that step, which re-writes just that one file.

WHY EACH SCRIPT RUNS AS ITS OWN PROCESS
----------------------------------------
Each of the three scripts builds its own Tk window (and the Scorecard one
does its work at import time, not inside a function). Importing them into
this launcher would mean several Tk mainloops fighting over one interpreter,
and the Scorecard script would start running the moment it was imported.
Running each one as a child process - exactly as if you double-clicked it -
keeps them working unchanged. Their console output is streamed into the
browser panel below, and their own popups (Year/Month pickers, "Done"
messages) appear on your desktop as normal.

Nothing is exposed to the network - the server only listens on the loopback
address, so no one else on the network can reach it. Closing this window (or
pressing Ctrl+C) shuts the launcher down.

Standard library only for this file. The three scripts still need their own
packages: requests, openpyxl, truststore, and (optionally) pywin32.
"""

import base64
import glob
import json
import os
import subprocess
import sys
import threading
import time
import webbrowser
from datetime import datetime
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlparse, parse_qs

HERE = Path(__file__).resolve().parent
SELF_PATH = Path(__file__).resolve()
EXTRACT_DIR = HERE / "scripts"
HISTORY_FILE = HERE / "launcher_history.json"
HOST = "127.0.0.1"
FIRST_PORT = 8756

SCRIPTS = [
    {
        "key": "jira",
        "title": "PBQT Revoked & Closed tickets",
        "blurb": "Asks for a year and month, pulls the matching PBQT tickets "
                 "from Jira Cloud and builds the pivot.",
        "makes": "Writes \u2192 Revoked & Closed tickets (Morningstar Jira Cloud).xlsx",
        "filename": "jira_revoked_closed.py",
        # Same glob pattern scorecard_automation.py itself searches for -
        # used to check this step's output actually exists, not just that it
        # was clicked at some point in this browser session.
        "produces_glob": "Revoked*Closed*.xlsx",
    },
    {
        "key": "master",
        "title": "Combined Production Master Sheet",
        "blurb": "Copies that month's Equity Dashboard workbooks, stacks every "
                 "Sample sheet and builds the two pivots.",
        "makes": "Writes \u2192 Combined Production Master Sheet.xlsx",
        "filename": "combined_production_master_sheet.py",
        "produces_glob": "Combined Production Master Sheet*.xlsx",
    },
    {
        "key": "scorecard",
        "title": "Scorecard Automation",
        "blurb": "Reads both workbooks above plus the roster and shrinkage "
                 "file, then fills each Scorecard.",
        "makes": "Fills \u2192 columns C, D, I, O, AF, AG, AT",
        "filename": "scorecard_automation.py",
        "requires": ["jira", "master"],
    },
]

"""Base64 payloads embedded in the launcher. Generated - do not hand-edit."""

