_PAYLOAD = {"jira": _B64_JIRA, "master": _B64_MASTER, "scorecard": _B64_SCORECARD}
PAGE_HTML = base64.b64decode(_B64_HTML).decode("utf-8")

# ---------------------------------------------------------------- state
LOCK = threading.RLock()      # reentrant: say() may be called while LOCK is already held
LOG = []                      # every line ever printed, in order
STATE = {}                    # key -> Ready / Queued / Running / Finished / ...
BUSY = False
CURRENT = None                # title of the step running right now
CURRENT_KEY = None            # its key, for looking up avg_seconds on the frontend
CURRENT_STARTED_AT = None     # epoch seconds - lets the browser compute elapsed/remaining
PROC = None                   # the child process, so Stop can reach it
HISTORY = {}                  # key -> list of past successful-run durations, in seconds
HISTORY_LIMIT = 5             # how many recent durations to keep per step


def say(line):
    with LOCK:
        LOG.append(line)


def load_history():
    global HISTORY
    if not HISTORY_FILE.exists():
        return
    try:
        raw = json.loads(HISTORY_FILE.read_text(encoding="utf-8"))
        HISTORY = {k: [float(v) for v in vs] for k, vs in raw.items()
                   if k in {s["key"] for s in SCRIPTS} and isinstance(vs, list)}
    except Exception as exc:
        say("!! Could not read %s (%s) - timing history starts fresh."
            % (HISTORY_FILE.name, exc))
        HISTORY = {}


def save_history():
    try:
        HISTORY_FILE.write_text(json.dumps(HISTORY, indent=2), encoding="utf-8")
    except Exception as exc:
        say("!! Could not save timing history: %s" % exc)


def record_duration(key, seconds):
    """Only called after a step exits with code 0 - a failed or stopped run
    doesn't represent a normal completion, so it's excluded from the average
    on purpose rather than skewing future estimates shorter than reality."""
    with LOCK:
        hist = HISTORY.setdefault(key, [])
        hist.append(round(seconds, 1))
        del hist[:-HISTORY_LIMIT]
    save_history()


def avg_seconds(key):
    hist = HISTORY.get(key) or []
    return round(sum(hist) / len(hist), 1) if hist else None


def spec_for(key):
    return next(s for s in SCRIPTS if s["key"] == key)


def script_path(key):
    return EXTRACT_DIR / spec_for(key)["filename"]


def output_folder():
    for var in ("OneDriveCommercial", "OneDrive"):
        value = os.environ.get(var)
        if value and Path(value).is_dir():
            root = Path(value)
            break
    else:
        root = Path.home() / "OneDrive - MORNINGSTAR INC"
    return root / "Data Operations - Quality Assurance Scorecard" / "Scorecard Automation"


def _output_exists(glob_pattern):
    """Whether a file matching this pattern is actually sitting in the
    output folder - checked with glob, the same tool the scripts themselves
    use to find each other's output, so this reflects the real prerequisite
    rather than "was Run clicked in this browser session"."""
    folder = output_folder()
    if not folder.is_dir():
        return False
    hits = [f for f in glob.glob(str(folder / glob_pattern))
            if not os.path.basename(f).startswith("~$")]
    return bool(hits)


def _prereqs_message(spec):
    """None if this step is ready to run. Otherwise a short, specific
    explanation of which upstream step(s)' output is still missing."""
    requires = spec.get("requires") or []
    if not requires:
        return None
    missing_titles = []
    for req_key in requires:
        req_spec = spec_for(req_key)
        pattern = req_spec.get("produces_glob")
        if pattern and not _output_exists(pattern):
            missing_titles.append(req_spec["title"])
    if not missing_titles:
        return None
    return "Waiting on: %s" % ", ".join(missing_titles)


def _open_in_file_manager(folder):
    if os.name == "nt":
        os.startfile(str(folder))
    elif sys.platform == "darwin":
        subprocess.Popen(["open", str(folder)])
    else:
        subprocess.Popen(["xdg-open", str(folder)])


# ------------------------------------------------------- embedded scripts
def extract_script(key, force=False):
    """Write one embedded script out to EXTRACT_DIR, unless it's already
    there and force=False - so hand edits to the extracted .py survive a
    restart, and only "Restore original" (force=True) overwrites them."""
    spec = spec_for(key)
    dest = script_path(key)
    if dest.exists() and not force:
        return True
    try:
        EXTRACT_DIR.mkdir(parents=True, exist_ok=True)
        data = base64.b64decode(_PAYLOAD[key])
        dest.write_bytes(data)
        say("|> %s%s %s" % ("Restored" if force else "Extracted",
                            "" if force else " (first run)", dest.name))
        return True
    except Exception as exc:
        say("!! Could not write %s - %s: %s" % (dest.name, type(exc).__name__, exc))
        return False


def ensure_all_extracted():
    say("== Scorecard launcher, %s" % datetime.now().strftime("%d %b %Y %H:%M"))
    say("   Folder: %s" % HERE)
    say("   Scripts live in: %s  (edit them freely - your changes are kept)" % EXTRACT_DIR)
    ok = True
    for spec in SCRIPTS:
        success = extract_script(spec["key"])   # logs via say() - must run outside LOCK
        with LOCK:
            STATE[spec["key"]] = "Ready" if success else "Error"
        ok = ok and success
    say("   All three scripts ready." if ok else
        "!! One or more scripts could not be written - check folder permissions.")
    say("")


# ------------------------------------------------------------ running
# Third-party packages each script needs, beyond the standard library - used
# only for the preflight check below, so a missing package is reported as a
# clear one-line fix instead of a raw traceback from inside the script.
REQUIRED_MODULES = {
    "jira": ["requests", "openpyxl"],
    "master": ["openpyxl"],
    "scorecard": ["openpyxl"],
}
_MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July",
                "August", "September", "October", "November", "December"]


def missing_dependencies(key):
    """Which required packages aren't importable in the interpreter that is
    about to run this script (sys.executable - the same one running this
    launcher). Checked with find_spec rather than a real import, so nothing
    is actually loaded. Returns [] if the check itself fails for any reason,
    so a flaky probe never blocks a run that would otherwise succeed."""
    mods = REQUIRED_MODULES.get(key, [])
    if not mods:
        return []
    probe = ("import importlib.util,sys;"
             "print(','.join(m for m in %r if importlib.util.find_spec(m) is None))" % mods)
    try:
        r = subprocess.run([sys.executable, "-c", probe],
                           capture_output=True, text=True, timeout=15)
        return [m for m in (r.stdout or "").strip().split(",") if m]
    except Exception:
        return []


def _valid_period(year, month):
    """Defense-in-depth: the browser's Year/Month pickers are closed dropdowns
    that can only emit sane values, but this validates independently of that -
    a request built by hand (or a future UI bug) can't pass a period one of
    the scripts would silently mis-handle. Returns (year_str_or_None,
    month_str_or_None); either half missing or out of range drops both, so a
    script always falls back to its own original default rather than getting
    a half-applied period."""
    try:
        y = int(year)
        m = int(month)
        if 2000 <= y <= 2100 and 1 <= m <= 12:
            return str(y), str(m)
    except (TypeError, ValueError):
        pass
    return None, None


def _halt_or_continue(key, keys, stop_on_fail):
    """Called after a step fails, either from the dependency check or from a
    nonzero exit code. Returns True if the caller should stop the sequence
    (and resets any not-yet-run steps back to Ready so they don't look
    stuck), or False if the caller should move on to the next step."""
    if not stop_on_fail:
        return False
    rest = [spec_for(k)["title"] for k in keys[keys.index(key) + 1:]]
    if rest:
        say("|> Sequence stopped. Not run: %s" % ", ".join(rest))
        say("")
        with LOCK:
            for k in keys[keys.index(key) + 1:]:
                STATE[k] = "Ready" if script_path(k).is_file() else "Error"
    return True


def runner(keys, stop_on_fail, year=None, month=None):
    global BUSY, CURRENT, CURRENT_KEY, CURRENT_STARTED_AT, PROC
    for key in keys:
        spec = spec_for(key)
        path = script_path(key)
        if not path.is_file():
            say("!! Skipping %s - %s is missing." % (spec["title"], path.name))
            with LOCK:
                STATE[key] = "Error"
            continue

        blocked_reason = _prereqs_message(spec)
        if blocked_reason:
            say("=" * 72)
            say("|> %s" % spec["title"])
            say("!! %s" % blocked_reason)
            say("   Run those first (or use \"Run all three\"), then try this step again.")
            say("=" * 72)
            say("")
            with LOCK:
                STATE[key] = "Blocked"
            if _halt_or_continue(key, keys, stop_on_fail):
                break
            continue

        missing = missing_dependencies(key)
        if missing:
            say("=" * 72)
            say("|> %s" % spec["title"])
            say("!! This Python is missing: %s" % ", ".join(missing))
            say("   Install into the SAME Python running this launcher, then try again:")
            say('   "%s" -m pip install %s' % (sys.executable, " ".join(missing)))
            say("=" * 72)
            say("")
            with LOCK:
                STATE[key] = "Failed"
            if _halt_or_continue(key, keys, stop_on_fail):
                break
            continue

        with LOCK:
            STATE[key] = "Running"
        CURRENT = spec["title"]
        CURRENT_KEY = key
        say("=" * 72)
        say("|> %s" % spec["title"])
        say("|  %s" % path)
        if year and month:
            try:
                month_name = _MONTH_NAMES[int(month) - 1]
                say("|  period: %s %s (pre-filled in the popup - change it there if needed)"
                    % (month_name, year))
            except (ValueError, IndexError):
                pass
        say("|  started %s" % datetime.now().strftime("%H:%M:%S"))
        say("=" * 72)

        env = dict(os.environ)
        env["PYTHONIOENCODING"] = "utf-8"
        env["PYTHONUTF8"] = "1"
        if year:
            env["SCORECARD_YEAR"] = str(year)
        if month:
            env["SCORECARD_MONTH"] = str(month)
        flags = getattr(subprocess, "CREATE_NO_WINDOW", 0) if os.name == "nt" else 0

        start_ts = time.time()
        try:
            PROC = subprocess.Popen(
                [sys.executable, "-u", str(path)],   # -u keeps output live
                cwd=str(path.parent),
                stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                stdin=subprocess.DEVNULL,
                text=True, encoding="utf-8", errors="replace", bufsize=1,
                env=env, creationflags=flags,
            )
        except Exception as exc:
            say("!! Could not start it - %s: %s" % (type(exc).__name__, exc))
            with LOCK:
                STATE[key] = "Failed"
            PROC = None
            CURRENT = None
            CURRENT_KEY = None
            CURRENT_STARTED_AT = None
            if _halt_or_continue(key, keys, stop_on_fail):
                break
            continue

        CURRENT_STARTED_AT = start_ts
        for line in PROC.stdout:
            say(line.rstrip("\n"))
        rc = PROC.wait()
        PROC = None
        duration = time.time() - start_ts
        CURRENT_STARTED_AT = None

        if rc == 0:
            record_duration(key, duration)   # only successful runs feed the estimate
            with LOCK:
                STATE[key] = "Finished"
            say("<| %s finished cleanly at %s (took %s)"
                % (spec["title"], datetime.now().strftime("%H:%M:%S"),
                   _format_duration(duration)))
            say("")
        else:
            with LOCK:
                STATE[key] = "Stopped" if rc < 0 else "Failed"
            say("!! %s ended with exit code %s after %s - see the output above."
                % (spec["title"], rc, _format_duration(duration)))
            say("")
            if _halt_or_continue(key, keys, stop_on_fail):
                break

    CURRENT = None
    CURRENT_KEY = None
    BUSY = False


def _format_duration(seconds):
    seconds = max(0, int(round(seconds)))
    h, rem = divmod(seconds, 3600)
    m, s = divmod(rem, 60)
    if h:
        return "%dh %dm" % (h, m)
    if m:
        return "%dm %ds" % (m, s)
    return "%ds" % s


def start_run(keys, stop_on_fail, year=None, month=None):
    global BUSY
    with LOCK:
        if BUSY:
            return False
        BUSY = True
        for key in keys:
            if script_path(key).is_file():
                STATE[key] = "Queued"
    threading.Thread(target=runner, args=(list(keys), stop_on_fail, year, month),
                     daemon=True).start()
    return True


def stop_run():
    proc = PROC
    if proc is None:
        return
    say("")
    say("|> Stop requested - ending the running script.")
    try:
        proc.terminate()
    except Exception as exc:
        say("!! Could not stop it: %s" % exc)


def open_output():
    folder = output_folder()
    if not folder.is_dir():
        say("!! Output folder not found: %s" % folder)
        say("   Check that OneDrive is signed in and the library is synced.")
        return
    try:
        _open_in_file_manager(folder)
        say("|> Opened %s" % folder)
    except Exception as exc:
        say("!! Could not open the folder: %s" % exc)


def open_scripts_folder():
    try:
        EXTRACT_DIR.mkdir(parents=True, exist_ok=True)
        _open_in_file_manager(EXTRACT_DIR)
        say("|> Opened %s" % EXTRACT_DIR)
    except Exception as exc:
        say("!! Could not open the folder: %s" % exc)


def restore_one(key):
    if not any(s["key"] == key for s in SCRIPTS):
        return
    if extract_script(key, force=True):
        with LOCK:
            STATE[key] = "Ready"


def read_script(key):
    """Returns (content_or_None, error_or_None) for the GET editor endpoint."""
    path = script_path(key)
    try:
        return path.read_text(encoding="utf-8"), None
    except Exception as exc:
        return None, "Could not read %s: %s" % (path.name, exc)


def save_script(key, content):
    """Validate the edited source as Python before writing it, so a save
    always leaves the file in a state Run can actually execute - the same
    idea as the missing-package check, just catching typos instead of
    imports. Returns (ok, error_or_None); the file is left untouched if
    validation fails."""
    path = script_path(key)
    try:
        compile(content, path.name, "exec")
    except SyntaxError as exc:
        where = "" if exc.lineno is None else " (line %d)" % exc.lineno
        return False, "SyntaxError: %s%s" % (exc.msg, where)
    except Exception as exc:
        return False, "%s: %s" % (type(exc).__name__, exc)
    try:
        path.write_text(content, encoding="utf-8")
    except Exception as exc:
        return False, "Could not write %s: %s" % (path.name, exc)
    with LOCK:
        STATE[key] = "Ready"
    say("|> Saved edits to %s" % path.name)
    return True, None


# --------------------------------------------------------------- server
class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *args):
        pass                      # the browser's own request log isn't useful here

    def _send(self, code, body, ctype):
        data = body.encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(data)

    def _json(self, payload):
        self._send(200, json.dumps(payload), "application/json; charset=utf-8")

    def do_GET(self):
        route = urlparse(self.path)

        if route.path in ("/", "/index.html", "/launcher.html"):
            self._send(200, PAGE_HTML, "text/html; charset=utf-8")
            return

        if route.path == "/api/script":
            key = (parse_qs(route.query).get("key") or [""])[0]
            if not any(s["key"] == key for s in SCRIPTS):
                self._json({"ok": False, "error": "Unknown step."})
                return
            content, error = read_script(key)
            if error:
                self._json({"ok": False, "error": error})
            else:
                self._json({"ok": True, "key": key, "content": content})
            return

        if route.path == "/api/poll":
            since = int((parse_qs(route.query).get("since") or ["0"])[0])
            with LOCK:
                lines = LOG[since:]
                payload = {
                    "busy": BUSY,
                    "current": CURRENT,
                    "current_key": CURRENT_KEY,
                    "current_started_at": CURRENT_STARTED_AT,
                    "next": len(LOG),
                    "lines": lines,
                    "steps": [{
                        "key": s["key"], "title": s["title"], "blurb": s["blurb"],
                        "makes": s["makes"],
                        "path": str(script_path(s["key"]).relative_to(HERE)),
                        "found": script_path(s["key"]).is_file(),
                        "state": STATE.get(s["key"], "Error"),
                        "avg_seconds": avg_seconds(s["key"]),
                        "run_count": len(HISTORY.get(s["key"], [])),
                        "blocked_reason": _prereqs_message(s),
                    } for s in SCRIPTS],
                }
            self._json(payload)
            return

        self._send(404, "Not found", "text/plain")

    def do_POST(self):
        route = urlparse(self.path)
        length = int(self.headers.get("Content-Length") or 0)
        try:
            body = json.loads(self.rfile.read(length) or b"{}")
        except Exception:
            body = {}

        if route.path == "/api/run":
            keys = [k for k in body.get("keys", []) if any(s["key"] == k for s in SCRIPTS)]
            year, month = _valid_period(body.get("year"), body.get("month"))
            started = start_run(keys, bool(body.get("stopOnFail", True)), year, month)
            if not started:
                say("!! A step is already running.")
            self._json({"ok": started})

        elif route.path == "/api/stop":
            stop_run()
            self._json({"ok": True})

        elif route.path == "/api/restore":
            key = body.get("key")
            if BUSY:
                say("!! Can't restore while a step is running.")
            else:
                restore_one(key)
            self._json({"ok": True})

        elif route.path == "/api/script":
            key = body.get("key")
            content = body.get("content")
            if not any(s["key"] == key for s in SCRIPTS) or content is None:
                self._json({"ok": False, "error": "Bad request."})
            elif BUSY:
                self._json({"ok": False, "error": "Can't save while a step is running."})
            else:
                ok, error = save_script(key, content)
                self._json({"ok": ok, "error": error})

        elif route.path == "/api/open-output":
            open_output()
            self._json({"ok": True})

        elif route.path == "/api/open-scripts":
            open_scripts_folder()
            self._json({"ok": True})

        else:
            self._send(404, "Not found", "text/plain")


def serve():
    load_history()
    ensure_all_extracted()

    server = None
    for port in range(FIRST_PORT, FIRST_PORT + 20):
        try:
            server = ThreadingHTTPServer((HOST, port), Handler)
            break
        except OSError:
            continue
    if server is None:
        print("Could not find a free port between %d and %d."
              % (FIRST_PORT, FIRST_PORT + 19))
        input("Press Enter to close.")
        return

    url = "http://%s:%d/" % (HOST, server.server_port)
    print("Scorecard launcher is running at %s" % url)
    print("Leave this window open. Press Ctrl+C here to shut it down.")
    threading.Timer(0.6, lambda: webbrowser.open(url)).start()

    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nShutting down.")
    finally:
        stop_run()
        server.server_close()


if __name__ == "__main__":
    serve()